import { I18n, type Messages } from "@lingui/core"
import { messages as deMessages } from "../locales/de/messages"
import { messages as enMessages } from "../locales/en/messages"
import type { MessageKey, MessageVars } from "./messages/en"

export type { MessageKey, MessageVars }

export type Locale = "en" | "de"

export const SOURCE_LOCALE: Locale = "en"

export const LOCALES: readonly Locale[] = ["en", "de"]

export const LOCALE_STORAGE_KEY = "openchat.locale"

/** Compiled Lingui bundles, generated by `pnpm --filter @openchat/web i18n:compile`. */
export const catalogs: Record<Locale, Messages> = {
  en: enMessages,
  de: deMessages,
}

/**
 * One instance per locale. The provider hands the active instance to Lingui's
 * React context; `translate()` reads the same instance from outside a tree.
 */
const instances: Record<Locale, I18n> = {
  en: new I18n({ locale: "en", messages: { en: enMessages } }),
  de: new I18n({ locale: "de", messages: { de: deMessages } }),
}

export function getI18n(locale: Locale): I18n {
  return instances[locale]
}

export function isLocale(value: unknown): value is Locale {
  return value === "en" || value === "de"
}

/**
 * Stored setting → navigator.language → English (spec 12).
 */
export function resolveLocale(): Locale {
  if (typeof window === "undefined") return SOURCE_LOCALE
  try {
    const stored = window.localStorage.getItem(LOCALE_STORAGE_KEY)
    if (isLocale(stored)) return stored
  } catch {
    // Storage may be unavailable (private mode, blocked cookies); fall through.
  }
  const preferred = typeof navigator !== "undefined" ? navigator.language : ""
  return preferred.toLowerCase().startsWith("de") ? "de" : "en"
}

/**
 * Locale-pinned translation for code that cannot use the React hook. The
 * provider's `t()` does the same lookup on the active instance.
 */
export function translate(locale: Locale, key: MessageKey, vars?: MessageVars): string {
  return getI18n(locale)._(key, vars)
}
